pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address accessControl) public {
        vm.assume(accessControl != address(0));
        try c.initialize(accessControl) {} catch {}
        // After initialize, the contract must never have _initialized == 0.
        // The bug version leaves it as 0 for a construction-context call, while the reference sets it to 1.
        // We can detect this by calling initialize again: reference reverts with InvalidInitialization, bug succeeds (or reverts differently).
        // But the rule can be tested by checking if the contract still treats itself as uninitialized.
        // Since _initialized is not directly exposed, we rely on re-calling initialize and checking for revert.
        bool reinitReverted;
        try c.initialize(accessControl) { reinitReverted = false; } catch { reinitReverted = true; }
        assertTrue(reinitReverted);
    }
}

