pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address accessControl) public {
        // Ensure accessControl is not the zero address to avoid InvalidInitialization in possible constructor path
        vm.assume(accessControl != address(0));
        bool firstOk = false;
        try c.initialize(accessControl) { firstOk = true; } catch { firstOk = false; }
        // If the first call failed, we cannot test further; the property only applies after a successful first call.
        vm.assume(firstOk);
        bool secondOk = false;
        try c.initialize(accessControl) { secondOk = true; } catch { secondOk = false; }
        // The reference must revert on second initialization (secondOk false), the mutant succeeds (secondOk true).
        assertTrue(!secondOk);
    }
}

