// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 index, uint256 lastUpdate, uint256 kink, uint256 slope0, uint256 slope1, uint256 maxMultiplier, uint256 minMultiplier, uint256 rate) public {
        vm.assume(index > 0);
        vm.assume(lastUpdate > 0 && lastUpdate < type(uint256).max);
        vm.assume(kink > 0 && kink < 1e27);
        vm.assume(slope0 > 0);
        vm.assume(slope1 > 0);
        vm.assume(maxMultiplier > minMultiplier && minMultiplier > 0);
        vm.assume(rate > 0);
        vm.warp(lastUpdate + 1);
        vm.assume(block.timestamp > lastUpdate);
        // We cannot directly set private state, so the property is expressed over the returned rate:
        // For any admissible parameters where elapsed != block.timestamp, the observed rate from c.rate()
        // must be finite (the call does not revert). The bug breaks this by using multiplication instead of
        // division, which may cause silent overflows or revert, but here the property is simply that the
        // reference call succeeds (does not revert) for valid inputs.
        bool ok = true;
        try c.rate(address(this), address(this)) returns (uint256) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}
